// =============================================================================
// calib_core.v — SENA calibration slice for Papilio Pro (Spartan-6 LX9)
// -----------------------------------------------------------------------------
// 784 -> 16 -> 10 stochastic slice with REAL trained weights in BRAM ROMs
// (w_hid.mem / w_out.mem, generated by host/make_papilio_mems.py from the A2
// checkpoint).  Bias is stored as weight column N_IN (input bit forced to 1).
//
// Datapath per pass (PAR = 1, matches the validated cycle formula):
//   S_HID : N_IN+1 ROM reads, bit-gated accumulate into 16 hidden accs
//   fire  : acc > Rnd, Rnd = LFSR slice in [-2^n_log2, 2^n_log2-1]
//   S_OUT : N_HID+1 reads, accumulate into 10 output accs
//   S_VOTE: vote update + confidence early-exit (shift-add, no multiplier)
//
// Everything is Verilog-2001 so ISE 14.7 XST accepts it.
// =============================================================================
`timescale 1ns/1ps
module calib_core #(
    parameter integer N_IN     = 784,
    parameter integer N_HID    = 16,
    parameter integer N_OUT    = 10,
    parameter integer W_BITS   = 16,
    parameter integer ACC_BITS = 28,
    parameter integer VOTE_BITS = 12,
    parameter integer T_MAX_HW = 63,      // hardware ceiling for passes counter
    // theta = TH_NUM / 2^TH_DEN_LOG2  (9/16 = 0.5625 ~ software theta 0.55)
    parameter integer TH_NUM = 9,
    parameter integer TH_DEN_LOG2 = 4,
    parameter W_HID_FILE = "w_hid.mem",
    parameter W_OUT_FILE = "w_out.mem"
) (
    input  wire                clk,
    input  wire                rst_n,
    input  wire                start,          // pulse: run one inference
    input  wire [5:0]          t_max,          // passes budget for this run
    input  wire                early_exit_en,  // 0 = always run t_max passes
    input  wire [3:0]          n_log2_hid,
    input  wire [3:0]          n_log2_out,
    input  wire [N_IN-1:0]     x_bits,
    output reg                 busy,
    output reg                 done,           // 1-cycle pulse
    output reg  [3:0]          pred,
    output reg  [5:0]          passes,
    output reg  [31:0]         run_cycles      // clk cycles for the whole run
);
    // ------------------------------------------------------------------ ROMs
    // hidden: word i = {w[15](hid15), ... , w[0](hid0)} for input i (i=N_IN is bias)
    reg [N_HID*W_BITS-1:0] rom_hid [0:N_IN];        // 785 x 256b
    reg [N_OUT*W_BITS-1:0] rom_out [0:N_HID];       // 17  x 160b
    initial begin
        $readmemh(W_HID_FILE, rom_hid);
        $readmemh(W_OUT_FILE, rom_out);
    end

    // ------------------------------------------------------------ LFSR bank
    // one Galois LFSR per neuron, same taps as rtl/lfsr32.v
    localparam [31:0] TAPS = 32'h8020_0003;
    reg [31:0] lfsr_hid [0:N_HID-1];
    reg [31:0] lfsr_out [0:N_OUT-1];
    integer k;

    // ------------------------------------------------------------- helpers
    function signed [ACC_BITS-1:0] sext_w;
        input signed [W_BITS-1:0] w;
        begin
            sext_w = {{(ACC_BITS-W_BITS){w[W_BITS-1]}}, w};
        end
    endfunction

    // Rnd = (lfsr & (2^(n+1)-1)) - 2^n  ->  uniform in [-2^n, 2^n-1]
    function signed [ACC_BITS-1:0] rnd_of;
        input [31:0] r;
        input [3:0]  nl2;
        reg [16:0] half, mask, bits;
        begin
            half = 17'd1 << nl2;
            mask = (half << 1) - 17'd1;
            bits = r[16:0] & mask;
            rnd_of = $signed({{(ACC_BITS-18){1'b0}}, 1'b0, bits})
                   - $signed({{(ACC_BITS-18){1'b0}}, 1'b0, half});
        end
    endfunction

    // -------------------------------------------------------------- state
    localparam S_IDLE = 3'd0, S_HID = 3'd1, S_HFIRE = 3'd2,
               S_OUT  = 3'd3, S_OFIRE = 3'd4, S_VOTE = 3'd5;
    reg [2:0] state;

    reg [9:0] idx;                        // 0..N_IN (bias step)
    reg [9:0] idx_d;
    reg       q_valid;
    reg [N_HID*W_BITS-1:0] q_hid;
    reg [N_OUT*W_BITS-1:0] q_out;
    reg       bit_d;

    reg signed [ACC_BITS-1:0] acc_hid [0:N_HID-1];
    reg signed [ACC_BITS-1:0] acc_out [0:N_OUT-1];
    reg [N_HID:0]  h_ext;                 // hidden bits + bias bit
    reg [N_OUT-1:0] o_bits;

    reg [VOTE_BITS-1:0] votes [0:N_OUT-1];
    reg [31:0] cyc_free;                  // free-running cycle counter
    reg [31:0] cyc_start;

    // extended input: bias position N_IN reads as 1
    wire x_at_idx = (idx == N_IN) ? 1'b1 :
                    ((idx < N_IN) ? x_bits[idx[9:0]] : 1'b0);

    // ---------------------------------------------------- vote combinatorics
    reg [VOTE_BITS-1:0] votes_next [0:N_OUT-1];
    reg [VOTE_BITS+7:0] sum_v, sum_num;
    reg [VOTE_BITS-1:0] max_v;
    reg [3:0]           argmax;
    integer c, b;
    always @* begin
        sum_v  = 0;
        max_v  = 0;
        argmax = 4'd0;
        for (c = 0; c < N_OUT; c = c + 1) begin
            votes_next[c] = votes[c] + {{(VOTE_BITS-1){1'b0}}, o_bits[c]};
            sum_v = sum_v + {8'd0, votes_next[c]};
            if (votes_next[c] > max_v) begin
                max_v  = votes_next[c];
                argmax = c[3:0];
            end
        end
        sum_num = 0;
        for (b = 0; b < 8; b = b + 1)
            if (TH_NUM[b]) sum_num = sum_num + (sum_v << b);
    end
    wire [VOTE_BITS+7:0] max_shift = {8'd0, max_v} << TH_DEN_LOG2;
    wire conf_ok = (sum_v != 0) && (max_shift >= sum_num);

    // ------------------------------------------------------------- main FSM
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            busy  <= 1'b0;
            done  <= 1'b0;
            pred  <= 4'd0;
            passes <= 6'd0;
            run_cycles <= 32'd0;
            cyc_free <= 32'd0;
            cyc_start <= 32'd0;
            idx <= 10'd0;
            idx_d <= 10'd0;
            q_valid <= 1'b0;
            bit_d <= 1'b0;
            h_ext <= 0;
            o_bits <= 0;
            for (k = 0; k < N_HID; k = k + 1) begin
                lfsr_hid[k] <= 32'hA5A5_0001 + k*32'h0101_0001;
                acc_hid[k]  <= 0;
            end
            for (k = 0; k < N_OUT; k = k + 1) begin
                lfsr_out[k] <= 32'h5A5A_1001 + k*32'h0202_0001;
                acc_out[k]  <= 0;
                votes[k]    <= 0;
            end
        end else begin
            done <= 1'b0;
            cyc_free <= cyc_free + 32'd1;
            // LFSRs advance every cycle while busy (free-running noise)
            if (busy) begin
                for (k = 0; k < N_HID; k = k + 1)
                    lfsr_hid[k] <= {1'b0, lfsr_hid[k][31:1]}
                                   ^ (lfsr_hid[k][0] ? TAPS : 32'b0);
                for (k = 0; k < N_OUT; k = k + 1)
                    lfsr_out[k] <= {1'b0, lfsr_out[k][31:1]}
                                   ^ (lfsr_out[k][0] ? TAPS : 32'b0);
            end

            case (state)
                S_IDLE: begin
                    q_valid <= 1'b0;
                    if (start) begin
                        busy   <= 1'b1;
                        passes <= 6'd0;
                        for (k = 0; k < N_OUT; k = k + 1) votes[k] <= 0;
                        for (k = 0; k < N_HID; k = k + 1) acc_hid[k] <= 0;
                        idx <= 10'd0;
                        cyc_start <= cyc_free;
                        state <= S_HID;
                    end
                end

                // ---- hidden layer: pipelined ROM read + accumulate --------
                S_HID: begin
                    // stage 1: present address, remember gating bit
                    q_hid  <= rom_hid[idx];
                    bit_d  <= x_at_idx;
                    idx_d  <= idx;
                    q_valid <= (idx <= N_IN);
                    // stage 2: accumulate previous word
                    if (q_valid && bit_d) begin
                        for (k = 0; k < N_HID; k = k + 1)
                            acc_hid[k] <= acc_hid[k]
                                + sext_w(q_hid[k*W_BITS +: W_BITS]);
                    end
                    if (idx == N_IN + 1) begin
                        state <= S_HFIRE;
                        idx   <= 10'd0;
                    end else
                        idx <= idx + 10'd1;
                end

                S_HFIRE: begin
                    for (k = 0; k < N_HID; k = k + 1)
                        h_ext[k] <= (acc_hid[k] > rnd_of(lfsr_hid[k], n_log2_hid));
                    h_ext[N_HID] <= 1'b1;      // bias bit for output layer
                    for (k = 0; k < N_OUT; k = k + 1) acc_out[k] <= 0;
                    q_valid <= 1'b0;
                    state <= S_OUT;
                end

                // ---- output layer ----------------------------------------
                S_OUT: begin
                    q_out  <= rom_out[idx];
                    bit_d  <= (idx <= N_HID) ? h_ext[idx[4:0]] : 1'b0;
                    q_valid <= (idx <= N_HID);
                    if (q_valid && bit_d) begin
                        for (k = 0; k < N_OUT; k = k + 1)
                            acc_out[k] <= acc_out[k]
                                + sext_w(q_out[k*W_BITS +: W_BITS]);
                    end
                    if (idx == N_HID + 1) begin
                        state <= S_OFIRE;
                        idx   <= 10'd0;
                    end else
                        idx <= idx + 10'd1;
                end

                S_OFIRE: begin
                    for (k = 0; k < N_OUT; k = k + 1)
                        o_bits[k] <= (acc_out[k] > rnd_of(lfsr_out[k], n_log2_out));
                    state <= S_VOTE;
                end

                // ---- vote + early-exit ------------------------------------
                S_VOTE: begin
                    for (k = 0; k < N_OUT; k = k + 1) votes[k] <= votes_next[k];
                    passes <= passes + 6'd1;
                    pred   <= argmax;
                    if ((early_exit_en && conf_ok)
                        || (passes + 6'd1 >= t_max)) begin
                        busy <= 1'b0;
                        done <= 1'b1;
                        run_cycles <= cyc_free - cyc_start;
                        state <= S_IDLE;
                    end else begin
                        for (k = 0; k < N_HID; k = k + 1) acc_hid[k] <= 0;
                        idx <= 10'd0;
                        q_valid <= 1'b0;
                        state <= S_HID;
                    end
                end
                default: state <= S_IDLE;
            endcase
        end
    end
endmodule
